async def _picking_auto_passed_reason(
    session: AsyncSession,
    tenant_id: uuid.UUID,
    supply: FbsSupply,
    orders: list[FbsOrder],
) -> str | None:
    if not orders:
        return None
    address_enabled = await tenant_settings_svc.is_address_storage_enabled(session, tenant_id)
    if not address_enabled:
        return (
            "Адресное хранение выключено: подбор отмечен пройденным, можно переходить к упаковке."
        )
    product_ids = {order.product_id for order in orders if order.product_id is not None}
    if not product_ids:
        return None
    regular_location = await session.scalar(
        select(StorageLocation.id)
        .join(InventoryBalance, InventoryBalance.storage_location_id == StorageLocation.id)
        .where(
            StorageLocation.tenant_id == tenant_id,
            StorageLocation.warehouse_id == supply.warehouse_id,
            StorageLocation.code != SORTING_LOCATION_CODE,
            InventoryBalance.tenant_id == tenant_id,
            InventoryBalance.product_id.in_(product_ids),
            InventoryBalance.quantity_unpacked > 0,
        )
        .limit(1)
    )
    if regular_location is None:
        return (
            "Товар не распределён по адресным ячейкам: подбор отмечен пройденным, "
            "можно переходить к упаковке."
        )
    return None


async def _inject_order_pick_fallback(
    session: AsyncSession,
    tenant_id: uuid.UUID,
    supply: FbsSupply,
    worklist_items: list[dict[str, Any]],
) -> None:
    if not worklist_items:
        return
    if not await tenant_settings_svc.is_address_storage_enabled(session, tenant_id):
        return
    sorting_location = await get_or_create_sorting_location(session, tenant_id, supply.warehouse_id)
    orders_by_id = {str(order.id): order for order in supply.orders}
    for item in worklist_items:
        order = orders_by_id.get(str(item.get("id")))
        if order is None or order.product_id is None:
            continue
        if order.pick_status == PICK_STATUS_PICKED or (
            supply.marketplace != "wb" and order.pack_status == PACK_STATUS_PACKED
        ):
            continue
        inventory = item.get("inventory")
        if not isinstance(inventory, dict):
            continue
        if inventory.get("locations"):
            continue
        inventory["available_unpacked"] = max(int(inventory.get("available_unpacked") or 0), 1)
        inventory["locations"] = [
            {
                "id": str(sorting_location.id),
                "code": sorting_location.code,
                "available_unpacked": 1,
            }
        ]


