            FbsPrintAsset.status == PRINT_ASSET_STATUS_READY,
        )
    )
    assets = {asset.fbs_trbx_id: asset for asset in result.scalars().all() if asset.fbs_trbx_id}
    for box in boxes:
        trbx_id = box["trbx_id"]
        if trbx_id:
            box["qr_asset"] = _map_print_asset(assets.get(uuid.UUID(str(trbx_id))))
    return boxes


