def _fbs_order_change_rows(
    connection: Connection, order: FbsOrder, actor: DocumentEventActor
) -> list[dict[str, object]]:
    rows: list[dict[str, object]] = []
    # Смена статуса заказа — главное событие его жизни: по ней восстанавливают,
    # когда заказ собрали, когда передали и когда Wildberries его подтвердил.
    status_change = _history_pair(order, "status")
    if status_change is not None:
        status_before, status_after = status_change
        rows.append(
            _event_row(
                tenant_id=order.tenant_id,
                document_type=DOCUMENT_TYPE_FBS_ORDER,
                document_id=order.id,
                event_type=EVENT_STATUS_CHANGED,
                actor=actor,
                qty=None,
                product_id=order.product_id,
                payload_json={
                    "status_before": str(status_before) if status_before else None,
                    "status_after": str(status_after) if status_after else None,
                    "wb_status": order.wb_status,
                },
            )
        )
    change = _history_pair(order, "supply_id")
    if change is None:
        return rows
    before, after = change
    for supply_id, event_type, qty_before, qty_after in (
        (before, EVENT_LINE_REMOVED, 1, 0),
        (after, EVENT_LINE_ADDED, 0, 1),
    ):
        if not isinstance(supply_id, uuid.UUID):
            continue
        tenant_id = connection.scalar(select(FbsSupply.tenant_id).where(FbsSupply.id == supply_id))
        if tenant_id is None:
            continue
        rows.append(
            _event_row(
                tenant_id=tenant_id,
                document_type=DOCUMENT_TYPE_FBS_SUPPLY,
                document_id=supply_id,
                event_type=event_type,
                actor=actor,
                qty=qty_after or qty_before,
                product_id=order.product_id,
                # Без ссылки на заказ событие поставки не привязать к нему:
                # история одного заказа показывала добавления всех остальных.
                payload_json={
                    "qty_before": qty_before,
                    "qty_after": qty_after,
                    "fbs_order_id": str(order.id),
                },
            )
        )
    return rows


def _write_rows_safely(connection: Connection, rows: Sequence[dict[str, object]]) -> None:
    for row in rows:
        savepoint = connection.begin_nested()
        try:
            _insert_event_row(connection, row)
        except Exception:
            savepoint.rollback()
            logger.exception(
                "document event write failed: document_type=%s document_id=%s event_type=%s",
                row["document_type"],
                row["document_id"],
                row["event_type"],
            )
        else:
            savepoint.commit()


def _insert_event_row(connection: Connection, row: dict[str, object]) -> None:
    connection.execute(insert(DocumentEvent).values(**row))


def _before_flush(session: Session, _flush_context: object, _instances: object) -> None:
    try:
        connection = session.connection()
        rows = _document_rows(session, connection)
        if not rows:
            return
        if connection.dialect.name == "postgresql":
            connection.execute(
                select(func.set_config("wms.document_event_writer", "application", True))
            )
        _write_rows_safely(connection, rows)
    except Exception:
        logger.exception("document event collection failed")


def install_document_event_tracking() -> None:
    """Install the transaction observer once for all sync and async ORM sessions."""
    if not event.contains(Session, "before_flush", _before_flush):
        event.listen(Session, "before_flush", _before_flush)
    if BackgroundTask.__call__ is not _run_system_document_background_task:
        BackgroundTask.__call__ = _run_system_document_background_task  # type: ignore[assignment]

                session,
                user.tenant_id,
                supply_id,
                http_client,
                type=type,
            )
        except shipment_svc.FbsShipmentError as exc:
            _raise_from_shipment_service(exc)
    await session.commit()
    media_type = "image/png" if type == "png" else "image/svg+xml"
    return Response(content=png_bytes, media_type=media_type)


@router.get("/{supply_id}/history")
async def get_fbs_supply_history(
    supply_id: uuid.UUID,
    user: Annotated[User, Depends(require_fbs_operator_access)],
    session: Annotated[AsyncSession, Depends(get_db)],
) -> dict[str, Any]:
    """Хронология поставки: заказы, подбор, упаковка, коды, печать, короба.

    Однотипные записи склеены: печать сорока стикеров — одна строка, а номера
    прячутся внутрь неё. Собирается из уже существующих записей, поэтому
    работает и по старым поставкам.
    """
    try:
        return await supply_history(session, tenant_id=user.tenant_id, supply_id=supply_id)
    except FbsOrderHistoryError as exc:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=str(exc)) from exc

