import { useCallback, useEffect, useRef, useState } from 'react'
import { Box, Paper, Stack, Typography } from '@mui/material'
import { CheckboxInput, ErrorNotice, PrimaryAction, SelectInput } from '../../ui-kit'
import { apiUrl } from '../../api'
import { readApiErrorMessage } from '../../utils/readApiErrorMessage'
import {
  DEFAULT_PRINT_LABEL_OPTIONS,
  resolvePrintTemplate,
  type PrintLabelOptions,
} from '../../utils/printTemplate'

type SellerOption = { id: string; name: string }

const FIELDS: Array<{ key: keyof PrintLabelOptions; label: string }> = [
  { key: 'include_size', label: 'Размер' },
  { key: 'include_color', label: 'Цвет' },
  { key: 'include_brand', label: 'Бренд' },
  { key: 'include_composition', label: 'Состав' },
]

/**
 * Состав этикетки ШК, закреплённый за продавцом.
 *
 * До 03.09.2026 настроить это было нельзя: хранилище шаблонов с привязкой к
 * продавцу существовало, но хранило только ленту печати, а состав самой
 * этикетки жил в момент печати и забывался. Порядок строк единый для всех и
 * здесь не настраивается — только что показывать, а что нет.
 */
export function FfLabelTemplatePanel({ token }: { token: string }) {
  const [sellers, setSellers] = useState<SellerOption[]>([])
  const [sellerId, setSellerId] = useState('')
  const [options, setOptions] = useState<PrintLabelOptions>(DEFAULT_PRINT_LABEL_OPTIONS)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [saved, setSaved] = useState(false)
  // Рубильник сборки. Пока он выключен, состав этикетки не настраивается вовсе
  // и панели нет: боевая сборка не должна иметь ни одной возможности повлиять
  // на то, что печатается сегодня.
  const [enabled, setEnabled] = useState<boolean | null>(null)

  // Ответ на прошлого продавца не должен записываться в галочки нового.
  // Переключились с А на Б, ответ А пришёл позже — и оператор сохранил бы
  // настройки А под именем Б, ничего не заметив.
  const requestedSellerRef = useRef('')

  const load = useCallback(async (id: string) => {
    setError(null)
    setSaved(false)
    requestedSellerRef.current = id
    try {
      const template = await resolvePrintTemplate(token, { sellerId: id })
      if (requestedSellerRef.current !== id) return
      setOptions(template.layout.label_options ?? DEFAULT_PRINT_LABEL_OPTIONS)
    } catch (cause) {
      if (requestedSellerRef.current !== id) return
      setError(cause instanceof Error ? cause.message : 'Не удалось загрузить настройку')
    }
  }, [token])

  useEffect(() => {
    if (enabled !== true) return
    void (async () => {
      try {
        const response = await fetch(apiUrl('/sellers'), {
          headers: { Authorization: `Bearer ${token}` },
        })
        if (!response.ok) return
        const rows = (await response.json()) as SellerOption[]
        setSellers(rows)
      } catch {
        // Список продавцов не загрузился — панель просто останется пустой,
        // ронять весь экран настроек из-за неё нельзя.
      }
    })()
  }, [token, enabled])

  useEffect(() => {
    void (async () => {
      try {
        const response = await fetch(apiUrl('/tenant/settings'), {
          headers: { Authorization: `Bearer ${token}` },
        })
        if (!response.ok) {
          setEnabled(false)
          return
        }
        const data = (await response.json()) as { label_template_enabled?: boolean }
        setEnabled(data.label_template_enabled === true)
      } catch {
        // Не смогли спросить — считаем выключенным. Показать панель, которой
        // сервер не даст сохранить, хуже, чем не показать ничего.
        setEnabled(false)
      }
    })()
  }, [token])

  useEffect(() => {
    if (sellerId) void load(sellerId)
  }, [sellerId, load])

  const save = async () => {
    if (!sellerId) return
    setBusy(true)
    setError(null)
    try {
      // Отдельная ручка состава: она меняет только галочки и не трогает ленту
      // печати продавца. Пока панель сохраняла шаблон целиком, она заодно
      // переписывала ленту на «один ШК», и у оператора без личной раскладки
      // из печати пропадал Честный знак.
      const response = await fetch(
        apiUrl('/operations/marking-codes/print-templates/seller-label-options'),
        {
          method: 'PUT',
          headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
          body: JSON.stringify({ seller_id: sellerId, label_options: options }),
        },
      )
      if (!response.ok) throw new Error(await readApiErrorMessage(response))
      setSaved(true)
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : 'Не удалось сохранить')
    } finally {
      setBusy(false)
    }
  }

  if (enabled !== true) {
    return null
  }

  return (
    <Paper variant="outlined" sx={{ p: 2, mb: 3 }} data-testid="ff-settings-label-panel">
      <Typography variant="subtitle1" gutterBottom>
        Этикетка товара
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 1.5 }}>
        Что печатать на этикетке ШК у этого продавца. Порядок строк единый для всех: размер,
        цвет, бренд, состав. Пустые поля товара не печатаются в любом случае.
      </Typography>
      <Stack spacing={2}>
        <Box sx={{ maxWidth: 320 }}>
          <SelectInput
            label="Продавец"
            value={sellerId}
            onChange={setSellerId}
            emptyLabel="Выберите продавца"
            options={sellers.map((one) => ({ value: one.id, label: one.name }))}
            testId="ff-label-seller"
          />
        </Box>
        {sellerId ? (
          <>
            <Stack direction="row" spacing={2} sx={{ flexWrap: 'wrap' }}>
              {FIELDS.map((field) => (
                <CheckboxInput
                  key={field.key}
                  label={field.label}
                  checked={options[field.key]}
                  onChange={(checked: boolean) => {
                    setSaved(false)
                    setOptions((prev) => ({ ...prev, [field.key]: checked }))
                  }}
                  testId={`ff-label-${field.key}`}
                />
              ))}
            </Stack>
            <Box>
              <PrimaryAction
                onClick={() => void save()}
                disabledReason={busy ? 'Сохраняется' : undefined}
                data-testid="ff-label-save"
              >
                Сохранить
              </PrimaryAction>
            </Box>
            {saved ? (
              <Typography variant="body2" color="success.main" data-testid="ff-label-saved">
                Сохранено: так теперь печатаются этикетки этого продавца.
              </Typography>
            ) : null}
          </>
        ) : null}
        {error ? <ErrorNotice testId="ff-label-error">{error}</ErrorNotice> : null}
      </Stack>
    </Paper>
  )
}

import { useCallback } from 'react'
import { apiUrl } from '../api'
import { resolveProductBarcodeOptions, type ProductLineDisplayMeta } from '../types/wbProductCatalog'
import { displayMetaToProductLabel } from './productBarcodePrint'
import { readApiErrorMessage } from './readApiErrorMessage'
import { useMarkingCodePrint } from './useMarkingCodePrint'

type MarkingOverviewResponse = {
  product: { requires_honest_sign: boolean }
  personal_pools: { available: number; printed: number }[]
  shared_baskets: { available: number }[]
}

export function sumPersonalAvailable(pools: { available: number }[]): number {
  return pools.reduce((sum, pool) => sum + (pool.available ?? 0), 0)
}

export function sumSharedBasketAvailable(baskets: { available: number }[]): number {
  return baskets.reduce((sum, basket) => sum + (basket.available ?? 0), 0)
}

export function computeMarkingAvailable(
  personalPools: { available: number }[],
  sharedBaskets: { available: number }[],
): number {
  return sumPersonalAvailable(personalPools) + sumSharedBasketAvailable(sharedBaskets)
}

export function computeMarkingAvailableFromInventory(
  personalAvailable: number,
  sharedBaskets: { available: number }[],
): number {
  return personalAvailable + sumSharedBasketAvailable(sharedBaskets)
}

export type OpenFfProductPrintOpts = {
  productId: string
  meta: ProductLineDisplayMeta
  documentNumber?: string | null
  /** База для печати (как qty_need_pack в упаковке). В каталоге не задаётся. */
  qtyNeedPack?: number
  /** catalog — своё поле «кол-во товаров»; packaging — база = qtyNeedPack, ЧЗ/ШК = множители на ед. */
  source?: 'catalog' | 'packaging'
  requiresHonestSign?: boolean
  markingAvailable?: number
  qtyMarkingPrinted?: number
  onPrinted?: () => void
}

function sumPersonalPrinted(pools: { printed: number }[]): number {
  return pools.reduce((sum, pool) => sum + (pool.printed ?? 0), 0)
}

async function fetchMarkingOverview(
  token: string,
  productId: string,
): Promise<MarkingOverviewResponse> {
  const res = await fetch(apiUrl(`/operations/marking-codes/products/${productId}/marking-overview`), {
    headers: { Authorization: `Bearer ${token}` },
  })
  if (!res.ok) {
    throw new Error(await readApiErrorMessage(res))
  }
  return (await res.json()) as MarkingOverviewResponse
}

/** Единая печать товара (как в отгрузке/упаковке): MarkingPrintDialog + конструктор ЧЗ. */
export function useFfProductMarkingPrint(token: string) {
  const { openPrint, dialog } = useMarkingCodePrint()

  const openCatalogProductPrint = useCallback(
    async (opts: OpenFfProductPrintOpts) => {
      let requiresHonestSign = opts.requiresHonestSign
      let markingAvailable = opts.markingAvailable
      let qtyMarkingPrinted = opts.qtyMarkingPrinted

      if (
        requiresHonestSign === undefined ||
        markingAvailable === undefined ||
        qtyMarkingPrinted === undefined
      ) {
        const overview = await fetchMarkingOverview(token, opts.productId)
        if (requiresHonestSign === undefined) {
          requiresHonestSign = overview.product.requires_honest_sign
        }
        if (markingAvailable === undefined) {
          markingAvailable = computeMarkingAvailable(
            overview.personal_pools,
            overview.shared_baskets ?? [],
          )
        }
        if (qtyMarkingPrinted === undefined) {
          qtyMarkingPrinted = sumPersonalPrinted(overview.personal_pools)
        }
      }

      const source =
        opts.source ?? (opts.qtyNeedPack != null && opts.qtyNeedPack > 0 ? 'packaging' : 'catalog')

      openPrint({
        token,
        source,
        productId: opts.productId,
        documentNumber: opts.documentNumber ?? null,
        qtyNeedPack: source === 'packaging' ? Math.max(1, opts.qtyNeedPack ?? 1) : 1,
        markingAvailable: markingAvailable ?? 0,
        qtyMarkingPrinted: qtyMarkingPrinted ?? 0,
        requiresHonestSign: requiresHonestSign ?? false,
        skuCode: opts.meta.sku_code,
        productName: opts.meta.product_name,
        productLabel: displayMetaToProductLabel(opts.meta),
        // WB-only остаётся в прежнем режиме; связанная Ozon-карточка добавляет
        // выбор реального кода в ту же форму, включая случай отсутствующих кодов.
        productBarcodeOptions: opts.meta.marketplace_bindings?.some((binding) => binding.marketplace === 'ozon')
          ? resolveProductBarcodeOptions(opts.meta)
          : undefined,
        packagingInstructions: opts.meta.packaging_instructions,
        unitsInPack: opts.meta.units_in_pack,
        onPrinted: opts.onPrinted ?? (() => {}),
      })
    },
    [openPrint, token],
  )

  return { openCatalogProductPrint, dialog }
}

async def _preview_selected_operations(
    session: AsyncSession, *, tenant_id: uuid.UUID, request: dict[str, Any]
